import {lessons,questions,chapters} from './data.js';
import {accuracy,topicStatus,topicMastered} from './adaptive.js';
import {escapeHTML as esc} from './math-ui.js';
export function progressHTML(state){let topics=state.profile?.topics||{},weak=lessons.filter(l=>topicStatus(state,l.id)==='Cần củng cố'),last=state.exams.at(-1),dueExam=!last||Date.now()-new Date(last.date).getTime()>7*86400000;return `<div class="eyebrow">Hồ sơ ninja · Theo từng chủ đề</div><h1>Biết rõ mình cần luyện gì.</h1><p>Thành thạo cần ít nhất 4 lần đúng độc lập, qua 3 ngày và 2 lượt; có câu tự gõ đáp án và bài mới hoặc vận dụng, độ chính xác gần đây ≥80%, lần tự làm gần nhất đúng. Tự đánh giá và dùng gợi ý chỉ hỗ trợ lịch ôn.</p><section class="panel"><h2>Lượt nên học tiếp</h2><p>${weak.length?`${weak.length} chủ đề cần củng cố. Bắt đầu với ${esc(weak[0].title)}.`:'Tiếp tục học câu mới xen câu đến hạn; chưa có bằng chứng yếu không có nghĩa là đã vững.'}</p><div class="actions"><button class="primary" data-card-start="${weak.length?'wrong':'learn'}">${weak.length?'Luyện câu sai':'Học ngay'}</button><button class="secondary" data-card-start="due">Ôn thẻ đến hạn</button>${dueExam?'<button class="secondary" data-go="exam">Đến lúc kiểm tra tổng hợp tuần này</button>':''}</div></section>${chapters.map((ch,i)=>`<h2 style="margin-top:28px">Chương ${i+1} · ${ch.topic}</h2><div class="table-wrap"><table><thead><tr><th>Chủ đề</th><th>Mức nắm</th><th>Đúng độc lập</th><th>Chính xác gần đây</th><th>Hỗ trợ / tự đánh giá</th><th>Ngày tự làm đúng</th></tr></thead><tbody>${lessons.filter(l=>l.ch===i).map(l=>{let r=topics[l.id];return `<tr><td><button class="text-button" data-lesson="${l.id}">${esc(l.title)}</button></td><td>${topicStatus(state,l.id)}</td><td>${r?.independentCorrect||0}</td><td>${r?.recent.some(e=>e.independent)?Math.round(accuracy(r)*100)+'%':'—'}</td><td>${r?.assisted||0} / ${r?.selfRatings||0}</td><td>${r?.independentDays.length||0}</td></tr>`}).join('')}</tbody></table></div>`).join('')}<p class="muted">Kết quả cũ và lịch ôn được giữ nguyên. Dữ liệu cũ chưa ghi mức hỗ trợ không tự chuyển thành bằng chứng độc lập.</p>`}
